/** Server time. Business rules never read the clock directly, so tests control it (PIX-10). */
export interface Clock {
  now(): Date;
}

/** Ids are generated by the application, not the database (database.md, section 3). */
export interface IdGenerator {
  next(): string;
}

/**
 * An append-only audit record (domain-model.md 3.5). Metadata never carries
 * passwords, PINs, tokens, a full CPF or a full Pix key.
 */
export interface AuditEvent {
  id: string;
  occurredAt: Date;
  actorType: 'USER' | 'SYSTEM' | 'STAFF';
  actorId: string | null;
  action: string;
  subjectType: string;
  subjectId: string;
  requestId: string | null;
  metadata: Record<string, string | number | boolean>;
}

/** Written in the same transaction as the operation it describes. */
export interface AuditTrail {
  record(event: AuditEvent): Promise<void>;
}

/**
 * One database transaction, shared by every module that takes part in a use
 * case (ADR 0010). Opaque on purpose: only infrastructure knows what is inside.
 */
export interface Transaction {
  readonly kind: 'transaction';
}

/** Runs the work in a single transaction: every module's writes commit together, or none. */
export interface UnitOfWork {
  run<T>(work: (tx: Transaction) => Promise<T>): Promise<T>;
}

/** The request an unexpected error broke: never its body, headers or user. */
export interface ReportedRequest {
  requestId: string;
  method: string;
  route: string;
}

/**
 * Where unexpected errors go to be looked at (CLAUDE.md, Observabilidade).
 * Refusals from the catalog are the API working and never reach it.
 */
export interface ErrorReporter {
  report(error: unknown, request: ReportedRequest): void;
}
